package com.pms.billing_service.grpc;

import billing.BillingRequest;
import billing.BillingResponse;
import billing.BillingServiceGrpc.BillingServiceImplBase;
import io.grpc.stub.StreamObserver;
import net.devh.boot.grpc.server.service.GrpcService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

// Similar to @RestController for REST, this tells Spring Boot to bind this class to the embedded gRPC server (Netty)
@GrpcService
public class BillingGrpcService extends BillingServiceImplBase {
    // Extends the base class generated by Protobuf from billing_service.proto

    private static final Logger log = LoggerFactory.getLogger(BillingGrpcService.class);

    @Override
    public void createBillingAccount(BillingRequest billingRequest, StreamObserver<BillingResponse> responseObserver) {
        log.info("createBillingAccount request received {}", billingRequest);

        // Business Logic Here

        BillingResponse response = BillingResponse.newBuilder()
                .setAccountId(billingRequest.getPatientId())
                .setStatus("ACTIVE")
                .build();

        responseObserver.onNext(response); // fulfills "returns (BillingResponse)"
        responseObserver.onCompleted(); // gRPC's equivalent of HTTP 200 OK
    }
}
